1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <algorithm>
12	#include <chrono>
13	#include <cstdint>
14	#include <cstdio>
15	#include <cstdlib>
16	#include <filesystem>
17	#include <optional>
18	#include <string>
19	#include <string_view>
20	#include <thread>
21	#include <vector>
22	
23	#include "argv.hpp"
24	#include "cli.hpp"
25	#include "elf_syms.hpp"
26	#include "engine_descriptor.hpp"
27	#include "engine_registry.hpp"
28	#include "hybrid.hpp"
29	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F3 overlap check)
30	#include "models.hpp"
31	#include "plan.hpp"
32	#include "process.hpp"
33	#include "repo_root.hpp"
34	#include "run_passthrough.hpp"
35	#include "run_plan.hpp"
36	#include "shm.hpp"
37	#include "state.hpp"
38	#include "state_diff.hpp"
39	#include "vsim_filter.hpp"
40	
41	namespace fs = std::filesystem;
42	
43	namespace andes_sim {
44	namespace {
45	
46	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
47	// success; on failure prints an error tagged with `ctx` and returns "". The
48	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
49	// missing path fails with a clear "ELF not found" instead of being handed to the
50	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
51	// up-front check run_hybrid already does.
52	std::string abs_elf(const std::string& path, const std::string& ctx) {
53	  std::error_code ec;
54	  fs::path abs = fs::absolute(path, ec);
55	  if (ec) {
56	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
57	                 ctx.c_str(), path.c_str());
58	    return "";
59	  }
60	  if (!fs::is_regular_file(abs, ec)) {
61	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
62	                 path.c_str());
63	    return "";
64	  }
65	  return abs.string();
66	}
67	
68	// Validate the lone-ELF positional shape the standalone models require: print
69	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
70	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
71	// spawns a --describe subprocess per Verilator build). `model` labels the error.
72	int check_one_elf(const Cli& cli, const char* model) {
73	  if (cli.positional.empty()) {
74	    std::fprintf(stderr,
75	                 "andesim run --mode %s: missing ELF (the workload to run; "
76	                 "e.g. a tests/fixtures/<name>.elf)\n",
77	                 model);
78	    return 2;
79	  }
80	  if (cli.positional.size() > 1) {
81	    std::fprintf(stderr,
82	                 "andesim run --mode %s: unexpected argument '%s' "
83	                 "(engine args go after --)\n",
84	                 model, cli.positional[1].c_str());
85	    return 2;
86	  }
87	  return 0;
88	}
89	
90	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
91	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
92	// from deep inside the engine. Both directions. Returns "" when they agree, when
93	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
94	// declares no xlen (cannot judge). Shared by cycle and hybrid: one wording.
95	std::string elf_engine_arch_error(const std::string& elf,
96	                                  const EngineDescriptor& eng) {
97	  const int ex = elf_xlen(elf);
98	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
99	  char buf[256];
100	  std::snprintf(buf, sizeof(buf),
101	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
102	                "or an rv%d ELF",
103	                ex, eng.id.c_str(), eng.xlen, ex);
104	  return buf;
105	}
106	
107	// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
108	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
109	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
110	// "fast-leg [qemu64]", "standalone [qemu64]"). Always returns 0 -- a dry run
111	// reports the plan, it does not run it.
112	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
113	                  const std::vector<std::string>& labels) {
114	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
115	  for (size_t i = 0; i < argvs.size(); ++i) {
116	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
117	                labels[i].c_str());
118	    std::printf("%s\n", render_argv(argvs[i]).c_str());
119	  }
120	  return 0;
121	}
122	
123	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
124	// and verbose [info] log (VsimFilter), relaying only the program's own output
125	// and any real diagnostics, then restate the lifted cycle count as andesim's own
126	// one-line result under the [andesim] prefix. The count is printed AFTER the run
127	// (the engine logs it at exit), so it follows the program output. Returns the
128	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
129	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
130	int run_cycle_clean(const std::vector<std::string>& argv) {
131	  VsimFilter filter;
132	  const int rc = run_line_filtered(
133	      argv, [&filter](int stream, std::string_view line) {
134	        std::FILE* dst = nullptr;
135	        switch (filter.classify(stream, line)) {
136	          case VsimFilter::Dest::kStdout: dst = stdout; break;
137	          case VsimFilter::Dest::kStderr: dst = stderr; break;
138	          case VsimFilter::Dest::kDrop: return;
139	        }
140	        std::fwrite(line.data(), 1, line.size(), dst);
141	        std::fputc('\n', dst);
142	      });
143	  if (const std::optional<uint64_t> c = filter.cycles())
144	    std::printf("[andesim] %llu cycles\n", static_cast<unsigned long long>(*c));
145	  return rc;
146	}
