80	std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
81	                                         std::string& err) {
82	  err.clear();
83	  std::vector<std::string> out;
84	
85	  // kanata ROI visualization first (marker/pc only; objdump rides kanata).
86	  if (!cli.kanata.empty()) {
87	    if (kind != "marker" && kind != "pc") {
88	      err = "--kanata is only supported with trigger marker or pc (got " + kind +
89	            ")";
90	      return {};
91	    }
92	    out.push_back("--kanata");
93	    out.push_back(cli.kanata);
94	    out.push_back("--kanata-roi");
95	    if (!cli.objdump.empty()) {
96	      out.push_back("--objdump");
97	      out.push_back(cli.objdump);
98	    }
99	  } else if (!cli.objdump.empty()) {
100	    err = "--objdump requires --kanata";
101	    return {};
102	  }
103	
104	  return out;
105	}
106	
107	}  // namespace andes_sim
