// See hybrid.hpp. Builds the ROI Trigger from the CLI, resolving pc boundaries.
#include "hybrid.hpp"

#include <cstdint>

#include "elf_syms.hpp"

namespace andes_sim {
namespace {

// Numeric value of a bare-hex PC string from resolve_pc. resolve_pc already
// validated the digits; an absurd >64-bit address (out_of_range) yields false,
// so the equal-ROI guard simply skips it (the bogus address fails downstream).
bool hex_pc(const std::string& s, uint64_t& out) {
  try {
    std::size_t pos = 0;
    out = std::stoull(s, &pos, 16);
    return pos == s.size();
  } catch (...) {
    return false;
  }
}

}  // namespace

Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
                       std::string& err) {
  err.clear();
  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
  // to fall back to marker, which masked running an unmarked ELF (the fast leg
  // ran to completion instead of draining at the ROI, surfacing only as a
  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
  if (cli.trigger.empty()) {
    err = "--trigger marker|pc is required "
          "(the ROI delimiter; see 'andesim run --help')";
    return {};
  }
  const std::string kind = cli.trigger;

  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params

  if (kind == "pc") {
    if (cli.pc_start.empty() || cli.pc_end.empty()) {
      err = "trigger pc requires --pc-start and --pc-end "
            "(a symbol name or 0x address)";
      return {};
    }
    std::string e1, e2;
    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
    if (!e1.empty()) { err = e1; return {}; }
    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
    if (!e2.empty()) { err = e2; return {}; }
    // A zero-length ROI (enter == exit) is degenerate: vsim resumes at the
    // enter PC and the exit trigger fires on that very instruction, so the
    // window measures nothing. Compare numerically -- a symbol and its literal
    // 0x address (or 0x0001000 vs 0x1000) are different strings, same PC.
    uint64_t a_enter = 0, a_exit = 0;
    if (hex_pc(enter, a_enter) && hex_pc(exit, a_exit) && a_enter == a_exit) {
      err = "trigger pc: --pc-start and --pc-end resolve to the same address "
            "0x" + enter + " (an empty ROI measures nothing)";
      return {};
    }
    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
  }

  err = "unknown trigger '" + kind + "' (want marker|pc)";
  return {};
}

std::string hybrid_hw_check(const EngineDescriptor& acc) {
  if (acc.xlen != 0 && acc.xlen != 64)
    return "engine " + acc.id + " is rv" + std::to_string(acc.xlen) +
           " (xlen=" + std::to_string(acc.xlen) +
           "); the hybrid fast leg (QEMU) is rv64-only";
  return "";
}

std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
                                         std::string& err) {
  err.clear();
  std::vector<std::string> out;

  // kanata ROI visualization first (marker/pc only; objdump rides kanata).
  if (!cli.kanata.empty()) {
    if (kind != "marker" && kind != "pc") {
      err = "--kanata is only supported with trigger marker or pc (got " + kind +
            ")";
      return {};
    }
    out.push_back("--kanata");
    out.push_back(cli.kanata);
    out.push_back("--kanata-roi");
    if (!cli.objdump.empty()) {
      out.push_back("--objdump");
      out.push_back(cli.objdump);
    }
  } else if (!cli.objdump.empty()) {
    err = "--objdump requires --kanata";
    return {};
  }

  return out;
}

}  // namespace andes_sim

// The phase-plan grammar driven by run_plan (F6), minus the dropped QEMU2
// step.
//
// A Plan is a list of Steps; each Step names an engine (by id, resolved against
// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
// order, threads the drained hybrid_state_v1 file forward, and returns each
// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
// mcycle.
#ifndef ANDESIM_PLAN_HPP
#define ANDESIM_PLAN_HPP

#include <map>
#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// The ROI delimiter for a step. `kind` is marker|pc; `params` carries
// kind-specific values (e.g. enter_pc, exit_pc) that F9 maps onto trigger
// args. F6 only exercises the default marker case (no params).
struct Trigger {
  std::string kind;
  std::map<std::string, std::string> params;
};

// One leg of a plan: which engine, which invoke role, under which trigger.
// `extra_args` are verbatim tokens appended after the filled template and the
// trigger args -- the seam for user-forwarded per-leg flags (e.g. the vsim
// leg's --kanata), which are orthogonal to the trigger.
struct Step {
  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
  Trigger trigger;
  std::vector<std::string> extra_args{};  // default-init: keeps 3-field Step{} literals warning-free
};

// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
// every leg so memory threads through.
struct Plan {
  std::string elf;          // path to the ELF every leg launches
  long long mem_size = 0;   // shared-mmap size in bytes
  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
  std::vector<Step> steps;
};

// What one drain step measured (read back from its state file), plus the
// leg's captured stdout -- the guest program's own output (UART/semihosting)
// rides the engine's stdout and must flow through to the user. `st` is the
// full drained record (verify_oracle F4: run --verify diffs the vsim drain
// against the oracle leg's in-process, after run_plan removed the files).
struct PhaseResult {
  unsigned long long mcycle = 0;
  unsigned long long minstret = 0;
  std::string out;
  hybrid_state_v1 st{};
};

// Aggregate outcome. `error` empty => every step matched its expected exit and
// drained a valid state file; `phases` then holds one entry per step in order.
struct PlanResult {
  std::string error;
  std::vector<PhaseResult> phases;
  // The concrete per-step argv run_plan built (after placeholder fill, qemu_cfg
  // staging, and state threading). Populated whether or not the steps spawn, so
  // a --dry-run can print the exact commands without executing them.
  std::vector<std::vector<std::string>> argvs;
  bool ok() const { return error.empty(); }
};

}  // namespace andes_sim

#endif  // ANDESIM_PLAN_HPP

