17	namespace fs = std::filesystem;
18	
19	namespace andes_sim {
20	
21	// The bundled functional engine(s). QEMU does not implement --describe, so the
22	// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
23	// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
24	// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
25	// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
26	// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
27	// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
28	// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
29	// scan whole-registry discovery would spawn.
30	EngineDescriptor builtin_qemu_arch(int xlen) {
31	  const bool rv32 = (xlen == 32);
32	  EngineDescriptor d;
33	  d.id = rv32 ? kQemuId32 : kQemuId64;
34	  d.type = "qemu";
35	  d.kind = "functional";
36	  d.xlen = xlen;
37	  d.triggers = {"marker", "pc"};
38	  d.state = {"drain"};
39	  d.source = "built-in";
40	
41	  d.roles = {"standalone"};
42	  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
43	    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
44	    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
45	    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
46	    // (empty for marker), folded by leg_trigger_args (F9).
47	    d.roles.push_back("fast-leg");
48	    d.invoke.push_back(
49	        {"fast-leg",
50	         {"{bin}", "-object",
51	          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
52	          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
53	          "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
54	          "enable=on,target=native", "-bios", "{elf}", "-plugin",
55	          "{plugin},outfile={state_out}{trigger}"}});
56	  }
57	
58	  // The standalone functional run (model=fast). andes_ae350's generic default
59	  // -cpu hangs the vplat fixtures, so pin a concrete andes core: the
60	  // vector-capable andes-ax46mpv (rv64) / andes-a46mpv (rv32). We pass NO vlen --
61	  // the cpu model's own QEMU default applies, so both scalar and vector binaries
62	  // run out of the box; a user who needs a specific width passes it via the
63	  // post-`--` -cpu (e.g. -cpu andes-ax46mpv,vlen=512), which still wins.
64	  // run_passthrough fills {bin}/{elf}.
65	  const char* fast_cpu = rv32 ? "andes-a46mpv" : "andes-ax46mpv";
66	  d.invoke.push_back(
67	      {"standalone",
68	       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
69	        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});
70	
71	  const std::string sys =
72	      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
73	  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
74	  if (const char* q = std::getenv(env); q && *q)
75	    d.bin_path = q;
76	  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
77	    d.bin_path = (fs::path(qd) / sys).string();
78	  else
79	    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
80	  return d;
81	}
82	
83	// rv64 qemu (back-compat: the default functional engine and hybrid fast leg).
84	EngineDescriptor builtin_qemu() { return builtin_qemu_arch(64); }
85	
86	namespace {
87	
88	constexpr int kDescribeTimeoutMs = 5000;
89	
90	bool is_executable_file(const fs::path& p) {
91	  std::error_code ec;
92	  if (!fs::is_regular_file(p, ec)) return false;
93	  return ::access(p.c_str(), X_OK) == 0;
94	}
95	
96	std::string read_file(const fs::path& p) {
97	  std::ifstream f(p, std::ios::binary);
98	  std::ostringstream ss;
99	  ss << f.rdbuf();
100	  return ss.str();
101	}
102	
103	// Ask one binary to describe itself: try `<bin> --describe`, else read the
104	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
105	// a human-readable note in `warn`.
106	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
107	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
108	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
109	    json::Parsed p = json::parse(r.out);
110	    if (p.ok) {
111	      std::string err = descriptor_from_json(p.value, d);
112	      if (err.empty()) {
113	        d.bin_path = bin.string();
114	        d.source = "--describe";
115	        return true;
116	      }
117	      warn = bin.string() + ": --describe JSON invalid: " + err;
118	    } else {
119	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
120	    }
121	  }
122	
123	  fs::path sidecar = bin;
124	  sidecar += ".json";
125	  std::error_code ec;
126	  if (fs::exists(sidecar, ec)) {
127	    json::Parsed p = json::parse(read_file(sidecar));
128	    if (p.ok) {
129	      EngineDescriptor sd;
130	      std::string err = descriptor_from_json(p.value, sd);
131	      if (err.empty()) {
132	        sd.bin_path = bin.string();
133	        sd.source = "sidecar";
134	        d = std::move(sd);
135	        return true;
136	      }
137	      warn = sidecar.string() + ": invalid descriptor: " + err;
138	    } else {
139	      warn = sidecar.string() + ": not JSON: " + p.error;
140	    }
141	  }
142	
143	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
144	  return false;
145	}
146	
147	// `prefix` filters candidate basenames; empty accepts any executable. The
148	// default VSIM_BIN_DIR scan passes "sim_"; a user-curated engines dir passes
149	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
150	// lives in the call site, not in this engine-agnostic scanner.
151	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
152	              std::set<std::string>& seen) {
153	  std::error_code ec;
154	  if (!fs::is_directory(dir, ec)) return;
155	
156	  std::vector<fs::path> entries;
157	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
158	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
159	
160	  for (const fs::path& p : entries) {
161	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
162	    if (!is_executable_file(p)) continue;
163	    EngineDescriptor d;
164	    std::string warn;
165	    if (describe_one(p, d, warn)) {
166	      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
167	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
168	    } else if (!warn.empty()) {
169	      out.warnings.push_back(warn);
170	    }
171	  }
172	}
173	
174	}  // namespace
175	
176	// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
177	// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
178	// finds the external vsim without a prior `source ./setup.sh`. Empty when
179	// unset everywhere -- there is no in-tree vsim to fall back to.
180	fs::path vsim_scan_dir(const fs::path& config_file) {
181	  return config_env_value("VSIM_BIN_DIR", config_file);
182	}
183	
184	fs::path vsim_scan_dir() {
185	  return vsim_scan_dir(repo_root() / "config.env");
186	}
187	
188	Discovery discover_engines() {
189	  Discovery out;
190	  std::set<std::string> seen;
191	
192	  EngineDescriptor qemu = builtin_qemu();
193	  seen.insert(qemu.id);
194	  out.engines.push_back(std::move(qemu));
195	
196	  // rv32 functional engine, listed alongside qemu so `list engines` shows both
197	  // (its binary is qemu-system-riscv32 under the same QEMU_BIN_DIR).
198	  EngineDescriptor qemu32 = builtin_qemu_arch(32);
199	  seen.insert(qemu32.id);
200	  out.engines.push_back(std::move(qemu32));
201	
202	  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
203	    std::stringstream ss(env);
204	    std::string dir;
205	    while (std::getline(ss, dir, ':'))
206	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
207	  } else {
208	    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
209	  }
210	  return out;
211	}
212	
213	}  // namespace andes_sim
